-- About page: rebuild the Mission section as balanced, vertically centred columns
-- (statement + link to Research on the left; a card with the intro and an
-- "Our work spans" list on the right), styled by the pab-* classes in
-- app/builder.css. The previous layout is kept as a page revision. Guarded on
-- node ids so an edited section is left alone.

INSERT INTO public.cms_page_revisions (page_id, title, content, seo, reason)
SELECT id, title || ' (before mission redesign)', published_content, seo, 'publish'
FROM public.cms_pages
WHERE slug = 'about'
  AND published_content->'sections'->1->>'id' = 'x4hgk8e1y'
  AND published_content->'sections'->1->'children'->0->>'id' = 'x9c7utm5g'
  AND published_content->'sections'->1->'children'->0->'children'->1->'children'->0->>'id' = 'xwsktzbea';

UPDATE public.cms_pages
SET content = jsonb_set(content, '{sections,1}', $pab${"id":"x4hgk8e1y","type":"section","props":{"tone":"auto","label":"Mission","width":"boxed","contentAlign":"left","verticalAlign":"top"},"advanced":{"className":"pab-mission"},"style":{"mobile":{"padding":{"top":"64px","bottom":"64px"}},"desktop":{"padding":{"top":"112px","bottom":"112px"}}},"children":[{"id":"x9c7utm5g","type":"columns","props":{"ratio":"equal","stackOn":"tablet","reverseOnStack":false},"style":{"desktop":{"gap":"72px","alignItems":"center"},"tablet":{"gap":"40px"}},"children":[{"id":"xqyugz1c6","type":"column","props":{},"children":[{"id":"xxbrw22y2","type":"heading","props":{"text":"Our mission","level":"p","preset":"eyebrow"},"animation":{"type":"fade","easing":"ease-out","duration":700}},{"id":"xd0h287rx","type":"heading","props":{"text":"To generate actionable, equity-centred research that improves public health and strengthens health systems.","level":"h2","preset":"default"},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":80}},{"id":"xpabmis01","type":"button","props":{"label":"Explore our research","link":{"href":"/research"},"variant":"link","size":"md","align":"left","icon":true},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":160}}]},{"id":"xgjgihi1z","type":"column","props":{},"advanced":{"className":"pab-mission-card"},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":160},"children":[{"id":"xwsktzbea","type":"richtext","props":{"html":"<p>We bring together researchers, students, healthcare providers, policymakers, and community partners to address complex health and social challenges through innovative, evidence-informed approaches.</p><h4>Our work spans</h4><ul><li><p>Health systems improvement</p></li><li><p>Food security</p></li><li><p>Social determinants of health</p></li><li><p>Patient and caregiver experiences</p></li><li><p>Structural drivers of health inequities</p></li></ul>"}}]}]}]}$pab$::jsonb),
    published_content = jsonb_set(published_content, '{sections,1}', $pab${"id":"x4hgk8e1y","type":"section","props":{"tone":"auto","label":"Mission","width":"boxed","contentAlign":"left","verticalAlign":"top"},"advanced":{"className":"pab-mission"},"style":{"mobile":{"padding":{"top":"64px","bottom":"64px"}},"desktop":{"padding":{"top":"112px","bottom":"112px"}}},"children":[{"id":"x9c7utm5g","type":"columns","props":{"ratio":"equal","stackOn":"tablet","reverseOnStack":false},"style":{"desktop":{"gap":"72px","alignItems":"center"},"tablet":{"gap":"40px"}},"children":[{"id":"xqyugz1c6","type":"column","props":{},"children":[{"id":"xxbrw22y2","type":"heading","props":{"text":"Our mission","level":"p","preset":"eyebrow"},"animation":{"type":"fade","easing":"ease-out","duration":700}},{"id":"xd0h287rx","type":"heading","props":{"text":"To generate actionable, equity-centred research that improves public health and strengthens health systems.","level":"h2","preset":"default"},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":80}},{"id":"xpabmis01","type":"button","props":{"label":"Explore our research","link":{"href":"/research"},"variant":"link","size":"md","align":"left","icon":true},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":160}}]},{"id":"xgjgihi1z","type":"column","props":{},"advanced":{"className":"pab-mission-card"},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":160},"children":[{"id":"xwsktzbea","type":"richtext","props":{"html":"<p>We bring together researchers, students, healthcare providers, policymakers, and community partners to address complex health and social challenges through innovative, evidence-informed approaches.</p><h4>Our work spans</h4><ul><li><p>Health systems improvement</p></li><li><p>Food security</p></li><li><p>Social determinants of health</p></li><li><p>Patient and caregiver experiences</p></li><li><p>Structural drivers of health inequities</p></li></ul>"}}]}]}]}$pab$::jsonb),
    updated_at = now()
WHERE slug = 'about'
  AND published_content->'sections'->1->>'id' = 'x4hgk8e1y'
  AND published_content->'sections'->1->'children'->0->>'id' = 'x9c7utm5g'
  AND published_content->'sections'->1->'children'->0->'children'->1->'children'->0->>'id' = 'xwsktzbea'
  AND content = published_content;
